import { useEffect, useState } from 'react';
import { AlertTriangle, ArrowRight, BarChart3, Gauge, Route, Scale, ShieldCheck, Timer, TrendingUp } from 'lucide-react';
import { api } from '../lib/api';
import type { MeasuredResponse, PublishedApcRow, RealizedWaitRow, RideSpeedRow } from '../types';
import { fmtInt, fmtNum1, fmtPct } from '../lib/format';
import { EmptyState, PanelSkeleton } from './PanelStates';
import SourceNote from './SourceNote';
import NewHereHint from './NewHereHint';

/**
 * Measured vs modeled (Stream B vs A): the street-level reality the modeling
 * stream is supposed to predict.
 *
 * - Realized transfer waits: what riders *actually* waited at the terminal
 *   (driven by observed lateness) vs. the scheduled wait the timetable
 *   promises. Where realized > scheduled, the modeled plan under-promises.
 * - Ride speeds: measured ride profiles showing the dwell/layover drag that
 *   timetable assumptions abstract away.
 *
 * Like every Stream B view, this is a read-only dumb reader of the collector's
 * committed artifacts — nothing is recomputed as a model.
 */

function StatCard({
  label,
  value,
  sub,
  tone,
}: {
  label: string;
  value: string;
  sub?: string;
  tone?: 'green' | 'amber' | 'neutral';
}) {
  const valueClass =
    tone === 'green' ? 'text-optimized' : tone === 'amber' ? 'text-bottleneck' : 'text-text-primary';
  return (
    <div className="card-glow rounded-xl border border-border bg-card p-3.5">
      <div className="text-[10px] font-semibold uppercase tracking-wider text-text-muted">{label}</div>
      <div className={`mt-1.5 text-2xl font-extrabold tabular-nums leading-none ${valueClass}`}>{value}</div>
      {sub && <div className="mt-1 text-[10px] leading-snug text-text-muted">{sub}</div>}
    </div>
  );
}

function SectionHeader({ icon, title, tone }: { icon: React.ReactNode; title: string; tone: 'green' | 'amber' | 'blue' }) {
  const cls =
    tone === 'green'
      ? 'bg-optimized/15 text-optimized'
      : tone === 'amber'
        ? 'bg-bottleneck/15 text-bottleneck'
        : 'bg-accent/15 text-accent';
  const edge = tone === 'green' ? 'edge-gradient-green' : tone === 'amber' ? 'edge-gradient-amber' : 'edge-gradient-blue';
  return (
    <div className="relative flex items-center gap-2.5 px-5 pt-5 pb-3">
      <div className={`absolute inset-x-0 top-0 h-0.5 ${edge}`} />
      <span className={`rounded-lg p-1.5 ${cls}`}>{icon}</span>
      <h3 className="text-sm font-bold text-text-primary">{title}</h3>
    </div>
  );
}

function DeltaCell({ delta }: { delta: number | null }) {
  if (delta == null || !Number.isFinite(delta)) return <span className="tabular-nums text-text-muted">—</span>;
  const worsens = delta > 0.05;
  const improves = delta < -0.05;
  const cls = worsens ? 'text-bottleneck' : improves ? 'text-optimized' : 'text-text-secondary';
  return (
    <span className={`tabular-nums font-bold ${cls}`}>
      {delta > 0 ? '+' : ''}
      {delta.toFixed(1)}
    </span>
  );
}

function WaitTable({ rows }: { rows: RealizedWaitRow[] }) {
  return (
    <div className="overflow-x-auto px-5 pb-4">
      <table className="data-table w-full text-left text-xs">
        <thead>
          <tr className="border-b border-border text-[10px] uppercase tracking-wider text-text-muted">
            <th className="py-1.5 pr-3 font-semibold">From → To</th>
            <th className="py-1.5 pr-3 font-semibold" title="Scheduled wait the timetable promises">Sched mean</th>
            <th className="py-1.5 pr-3 font-semibold">Realized mean</th>
            <th className="py-1.5 pr-3 font-semibold">Δ</th>
            <th className="py-1.5 pr-3 font-semibold" title="Realized worst-case wait (90th percentile)">Realized p90</th>
            <th className="py-1.5 text-right font-semibold">Missed</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr key={`${r.from_route}|${r.to_route}`} className="border-b border-border/50 text-text-secondary">
              <td className="py-2 pr-3 whitespace-nowrap font-bold text-text-primary">
                {r.from_route} <ArrowRight className="inline h-3 w-3 text-text-muted" /> {r.to_route}
              </td>
              <td className="py-2 pr-3 tabular-nums">{fmtNum1(r.sched_mean_min)}</td>
              <td className="py-2 pr-3 tabular-nums font-semibold text-text-primary">{fmtNum1(r.realized_mean_min)}</td>
              <td className="py-2 pr-3">
                <DeltaCell delta={r.delta_min} />
              </td>
              <td className="py-2 pr-3 tabular-nums">{fmtNum1(r.realized_p90_min)}</td>
              <td className="py-2 text-right tabular-nums">
                {r.realized_missed_share != null ? fmtPct(r.realized_missed_share * 100) : '—'}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function CaptureTable({ rows }: { rows: PublishedApcRow[] }) {
  return (
    <div className="overflow-x-auto px-5 pb-4">
      <table className="data-table w-full text-left text-xs">
        <thead>
          <tr className="border-b border-border text-[10px] uppercase tracking-wider text-text-muted">
            <th className="py-1.5 pr-3 font-semibold">Route</th>
            <th className="py-1.5 pr-3 font-semibold">Name</th>
            <th className="py-1.5 pr-3 text-right font-semibold">Published (APC)</th>
            <th className="py-1.5 pr-3 text-right font-semibold" title="Ground-truth calibrated lower-bound floor from the feed">Measured floor</th>
            <th className="py-1.5 text-right font-semibold">Capture</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => {
            const cap = r.capture_pct;
            const low = cap != null && cap < 15;
            return (
              <tr key={r.route} className="border-b border-border/50 text-text-secondary">
                <td className="py-2 pr-3 whitespace-nowrap font-bold text-text-primary">Route {r.route}</td>
                <td className="py-2 pr-3 text-text-muted">{r.long_name}</td>
                <td className="py-2 pr-3 text-right tabular-nums">{fmtInt(r.published_boardings)}</td>
                <td className="py-2 pr-3 text-right tabular-nums">{fmtInt(r.measured_floor)}</td>
                <td className="py-2 text-right">
                  <span className={`inline-flex items-center gap-1.5 tabular-nums font-bold ${low ? 'text-bottleneck' : 'text-text-primary'}`}>
                    {fmtPct(cap)}
                    <span className="inline-block h-1.5 w-10 overflow-hidden rounded-full bg-bg">
                      <span
                        className={`block h-full rounded-full ${low ? 'bg-bottleneck' : 'bg-optimized/70'}`}
                        style={{ width: `${Math.max(2, Math.min(100, cap ?? 0))}%` }}
                      />
                    </span>
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function SpeedTable({ rows }: { rows: RideSpeedRow[] }) {
  return (
    <div className="overflow-x-auto px-5 pb-4">
      <table className="data-table w-full text-left text-xs">
        <thead>
          <tr className="border-b border-border text-[10px] uppercase tracking-wider text-text-muted">
            <th className="py-1.5 pr-3 font-semibold">Route</th>
            <th className="py-1.5 pr-3 font-semibold" title="incl. dwell/layover at stops">Avg (all time)</th>
            <th className="py-1.5 pr-3 font-semibold" title="moving time only, stops excluded">Avg moving</th>
            <th className="py-1.5 pr-3 font-semibold">Peak</th>
            <th className="py-1.5 pr-3 font-semibold" title="Sub-5 km/h segments (stop dwell, signals, layovers)">Stalls</th>
            <th className="py-1.5 pr-3 font-semibold">Dist</th>
            <th className="py-1.5 text-right font-semibold">Elapsed</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => {
            const all = r.avg_kmh_incl_stops ?? null;
            const moving = r.avg_kmh_moving ?? null;
            const drag =
              all != null && moving != null && moving > 0 ? (1 - all / moving) * 100 : null;
            return (
              <tr key={`${r.vehicle_id}|${r.trip_id}`} className="border-b border-border/50 text-text-secondary">
                <td className="py-2 pr-3 whitespace-nowrap font-bold text-text-primary">Route {r.route}</td>
                <td className="py-2 pr-3 tabular-nums">{fmtNum1(all)}</td>
                <td className="py-2 pr-3 tabular-nums font-semibold text-text-primary">{fmtNum1(moving)}</td>
                <td className="py-2 pr-3 tabular-nums">{fmtNum1(r.peak_kmh)}</td>
                <td className="py-2 pr-3 tabular-nums">
                  {fmtInt(r.stall_segments)}
                  {drag != null && drag > 25 && (
                    <span className="ml-1 text-[10px] text-bottleneck">−{drag.toFixed(0)}%</span>
                  )}
                </td>
                <td className="py-2 pr-3 tabular-nums">{fmtNum1(r.distance_km)} km</td>
                <td className="py-2 text-right tabular-nums">{fmtNum1(r.elapsed_min)} min</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default function MeasuredVsModeledPanel() {
  const [data, setData] = useState<MeasuredResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let active = true;
    api
      .measured()
      .then((d) => {
        if (active) {
          setData(d);
          setError(null);
        }
      })
      .catch((e) => {
        if (active) setError(e instanceof Error ? e.message : String(e));
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, []);

  if (loading && !data) return <PanelSkeleton label="Loading measured vs modeled…" />;
  if (error && !data) {
    return (
      <div role="alert" className="rounded-xl border border-danger/40 bg-danger/10 p-6 text-sm text-danger">
        Could not load measured-vs-modeled data: {error}
      </div>
    );
  }
  if (!data) return null;

  const waits = data.realized_waits;
  const speeds = data.ride_speeds;
  const apc = data.published_apc;
  const dw = waits.departure_weighted;

  return (
    <div className="flex flex-col">
      {/* header */}
      <div className="relative overflow-hidden rounded-2xl border border-border bg-card px-5 py-5">
        <div className="absolute inset-x-0 top-0 h-1 edge-gradient-blue" />
        <div className="flex items-center gap-2.5">
          <span className="rounded-xl bg-accent/15 p-2">
            <Scale className="h-5 w-5 text-accent" />
          </span>
          <h2 className="text-base font-bold text-text-primary">Measured vs modeled</h2>
          <span className="inline-flex items-center gap-1 rounded-full border border-optimized/30 bg-optimized/10 px-2 py-0.5 text-[10px] font-semibold text-optimized">
            <ShieldCheck className="h-3 w-3" /> measured
          </span>
        </div>
        <p className="mt-2 text-xs leading-relaxed text-text-muted">
          Street-level reality — realized transfer waits, ride speeds, and the published-APC capture
          ratios — against the numbers the model plans on. If riders actually wait longer than the
          timetable claims, that gap is real world, not a shortfall in the re-phasing math.
        </p>
      </div>

      <div className="mt-3">
        <NewHereHint text="This is the honest-check page: Stream B (what happened) vs Stream A (what we'd change). When realized waits exceed scheduled waits, lateness pushes riders over the plan — and every optimized plan must be read against that reality, not the bare timetable." />
      </div>

      <div className="mt-4 flex flex-col gap-4">
        {/* ---- narrative summary ---- */}
        {dw && waits.available && (
          <div className="overflow-hidden rounded-2xl border border-border bg-card">
            <div className="px-5 py-4">
              <div className="flex items-center gap-2 text-xs font-bold text-text-primary">
                {dw.delta_min > 0.5 ? (
                  <><AlertTriangle className="h-4 w-4 text-bottleneck" /> What this means for the model</>
                ) : dw.delta_min < -0.5 ? (
                  <><ShieldCheck className="h-4 w-4 text-optimized" /> The model's assumptions hold up</>
                ) : (
                  <><ShieldCheck className="h-4 w-4 text-accent" /> Realized and scheduled waits are close</>
                )}
              </div>
              {dw.delta_min > 0.5 ? (
                <p className="mt-2 text-[11px] leading-relaxed text-text-muted">
                  Riders wait <b className="text-bottleneck">~{dw.delta_min.toFixed(1)} min longer</b> than the
                  timetable promises, departure-weighted. That means every optimized schedule built on
                  the bare timetable <b>underestimates real transfer pain</b> — the re-phasing math is
                  correct, but its input assumptions are optimistic. When interpreting Fix transfers
                  results, add {dw.delta_min.toFixed(1)} min to the modeled wait for a more honest picture.
                </p>
              ) : dw.delta_min < -0.5 ? (
                <p className="mt-2 text-[11px] leading-relaxed text-text-muted">
                  Riders actually wait <b className="text-optimized">~{Math.abs(dw.delta_min).toFixed(1)} min less</b> than
                  the timetable says — schedule padding (drivers holding at timepoints) is absorbing
                  lateness before it hits the connection. The model's assumptions are conservative here.
                </p>
              ) : (
                <p className="mt-2 text-[11px] leading-relaxed text-text-muted">
                  The {dw.delta_min > 0 ? '+' : ''}{dw.delta_min.toFixed(1)} min gap between realized and scheduled waits
                  is small — the timetable assumptions roughly match what riders experience.
                </p>
              )}
              {waits.rows.length > 0 && (
                <div className="mt-3 flex items-center gap-3 text-[10px] text-text-muted">
                  <span>Worst gap: <b className="text-text-primary">{waits.rows[0].from_route} → {waits.rows[0].to_route}</b> (+{(waits.rows[0].delta_min ?? 0).toFixed(1)} min)</span>
                  <span>·</span>
                  <span>{waits.n_pairs} route pairings · {waits.n_departures} departures</span>
                </div>
              )}
            </div>
          </div>
        )}

        {/* ---- speed drag callouts ---- */}
        {speeds.available && speeds.rows.length > 0 && (() => {
          const draggy = speeds.rows
            .filter((r) => {
              const all = r.avg_kmh_incl_stops;
              const moving = r.avg_kmh_moving;
              return all != null && moving != null && moving > 0 && (1 - all / moving) > 0.25;
            })
            .sort((a, b) => {
              const dragA = 1 - (a.avg_kmh_incl_stops ?? 0) / (a.avg_kmh_moving ?? 1);
              const dragB = 1 - (b.avg_kmh_incl_stops ?? 0) / (b.avg_kmh_moving ?? 1);
              return dragB - dragA;
            })
            .slice(0, 3);
          if (draggy.length === 0) return null;
          return (
            <div className="overflow-hidden rounded-2xl border border-amber-500/30 bg-amber-500/5">
              <div className="px-5 py-4">
                <div className="flex items-center gap-2 text-xs font-bold text-amber-400">
                  <Route className="h-4 w-4" /> Routes where dwell eats the most speed
                </div>
                <p className="mt-1.5 text-[11px] leading-relaxed text-text-muted">
                  These routes lose &gt;25% of their moving speed to stop dwell, signals, and layovers —
                  the optimizer should assume slower in-service times for these corridors.
                </p>
                <div className="mt-3 flex flex-wrap gap-2">
                  {draggy.map((r) => {
                    const drag = Math.round((1 - (r.avg_kmh_incl_stops ?? 0) / (r.avg_kmh_moving ?? 1)) * 100);
                    return (
                      <span key={`${r.vehicle_id}|${r.trip_id}`} className="inline-flex items-center gap-1.5 rounded-md border border-amber-500/30 bg-card-hover px-2.5 py-1.5 text-[11px]">
                        <span className="font-bold text-text-primary">Route {r.route}</span>
                        <span className="text-amber-400">−{drag}% speed</span>
                        <span className="text-text-muted">{fmtNum1(r.avg_kmh_incl_stops)} km/h all-in vs {fmtNum1(r.avg_kmh_moving)} moving</span>
                      </span>
                    );
                  })}
                </div>
              </div>
            </div>
          );
        })()}

        {/* realized waits */}
        {/* realized waits */}
        <section className="overflow-hidden rounded-2xl border border-border bg-card">
          <SectionHeader
            icon={<Timer className="h-4 w-4" />}
            title={`Realized transfer waits — ${waits.venue ?? 'terminal'}`}
            tone="blue"
          />
          {waits.available && waits.rows.length > 0 ? (
            <>
              <div className="grid grid-cols-2 gap-2.5 px-5 pb-2 sm:grid-cols-4">
                <StatCard
                  label="Scheduled mean wait"
                  value={dw ? fmtNum1(dw.sched_mean_min) : '—'}
                  sub="minutes the timetable promises"
                />
                <StatCard
                  label="Realized mean wait"
                  value={dw ? fmtNum1(dw.realized_mean_min) : '—'}
                  sub="departure-weighted, observed"
                  tone={(dw?.delta_min ?? 0) > 0 ? 'amber' : 'green'}
                />
                <StatCard
                  label="Δ from schedule"
                  value={dw ? `${dw.delta_min > 0 ? '+' : ''}${dw.delta_min.toFixed(2)}` : '—'}
                  sub="minutes riders wait beyond plan"
                  tone={(dw?.delta_min ?? 0) > 0 ? 'amber' : 'green'}
                />
                <StatCard
                  label="Pairings / departures"
                  value={`${fmtInt(waits.n_pairs)} / ${fmtInt(waits.n_departures)}`}
                  sub="route pairings · of departures"
                />
              </div>
              {dw && dw.delta_min > 0.05 && (
                <div className="mx-5 mb-2 flex items-start gap-2 rounded-lg border border-bottleneck/30 bg-bottleneck/10 px-3 py-2 text-[11px] leading-snug text-bottleneck">
                  <TrendingUp className="mt-0.5 h-3.5 w-3.5 shrink-0" />
                  On average riders wait <b>{dw.delta_min.toFixed(1)}&nbsp;min&nbsp;longer</b> than the
                  schedule says — the realized transfers this panel measures exceed the modeled plan.
                </div>
              )}
              <WaitTable rows={waits.rows.slice(0, 12)} />
              <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="text-[10px] text-text-muted">
                  Δ = realized mean − scheduled mean. Sorted by worsening Δ. Missed = share of departures
                  that miss the connection in reality.
                </span>
                <SourceNote source={waits.file ?? 'realized_waits.csv'} />
              </div>
            </>
          ) : (
            <div className="px-5 pb-5">
              <EmptyState
                title="No realized-waits analysis yet"
                hint="Run scripts/realized_waits.py against the collector's obs_lateness.csv to produce this view."
              />
            </div>
          )}
        </section>

        {/* ride speeds */}
        <section className="overflow-hidden rounded-2xl border border-border bg-card">
          <SectionHeader icon={<Gauge className="h-4 w-4" />} title="Ride speeds (measured)" tone="green" />
          {speeds.available && speeds.rows.length > 0 ? (
            <>
              <div className="px-5 pb-3 text-[11px] leading-relaxed text-text-muted">
                Ground-truth-joined GTFS-RT poll trails: average speed including stops (dwell/layover
                drag) vs. moving speed only. “Stalls” count sub-5 km/h segments — stop dwell, signals,
                layovers.
              </div>
              <SpeedTable rows={speeds.rows} />
              <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="text-[10px] text-text-muted">
                  Rows with an implausible multi-day elapsed window are poll-trail artifacts and sort to
                  the bottom.
                </span>
                <SourceNote source={speeds.file ?? 'ride_speeds.csv'} />
              </div>
            </>
          ) : (
            <div className="px-5 pb-5">
              <EmptyState
                title="No ride-speed profiles yet"
                hint="Ride speeds come from ground-truth-joined poll trails. Run scripts/ride_speeds.py after collecting a few days."
              />
            </div>
          )}
        </section>

        {/* published APC vs measured floor */}
        <section className="overflow-hidden rounded-2xl border border-border bg-card">
          <SectionHeader
            icon={<BarChart3 className="h-4 w-4" />}
            title="Published APC vs measured floor — capture ratios"
            tone="blue"
          />
          {apc.available && apc.rows.length > 0 ? (
            <>
              <div className="grid grid-cols-2 gap-2.5 px-5 pb-2 sm:grid-cols-4">
                <StatCard
                  label="Mean capture"
                  value={fmtPct(apc.mean_capture_pct)}
                  sub={`of true boardings the feed floor observes`}
                  tone="amber"
                />
                <StatCard
                  label="Published boardings / day"
                  value={fmtInt(apc.total_published)}
                  sub="the 10 routes MiWay publishes APC for"
                />
                <StatCard
                  label="Measured floor / day"
                  value={fmtInt(apc.total_measured)}
                  sub="ground-truth calibrated lower bound"
                />
                <StatCard
                  label="Routes compared"
                  value={fmtInt(apc.n_routes)}
                  sub={apc.period ? `${apc.period} · ${apc.day_type}` : undefined}
                />
              </div>
              <div className="mx-5 mb-2 flex items-start gap-2 rounded-lg border border-accent/30 bg-accent/10 px-3 py-2 text-[11px] leading-snug text-accent">
                <ShieldCheck className="mt-0.5 h-3.5 w-3.5 shrink-0" />
                These are the official APC counts the whole ridership layer is calibrated against. A
                capture below 100% is expected — the feed only sees <b>~1 in 4</b> true boardings as a
                load-floor lower bound — so low routes like <b>42</b> (11%) mean the published figure
                carries most of the story there.
              </div>
              {apc.network && (
                <div className="mx-5 mb-2 flex flex-wrap items-center gap-x-5 gap-y-1 rounded-lg border border-border bg-bg/40 px-3 py-2 text-[11px] leading-snug text-text-secondary">
                  <span className="font-semibold text-text-primary">Network anchors (weekday)</span>
                  <span>
                    <b className="tabular-nums">{fmtInt(apc.network.calibrated_weekday)}</b> our calibrated layer
                  </span>
                  <span>
                    <b className="tabular-nums">{fmtInt(apc.network.anchor_2024_weekday)}</b> published-implied 2024
                  </span>
                  <span>
                    <b className="tabular-nums">{fmtInt(apc.network.anchor_2025_weekday)}</b> published-implied 2025
                  </span>
                  <span className="text-text-muted">
                    MiWay publishes per-route boardings only for the Oct 2024 top-10 — the 2025 report
                    gives network annual figures (52.1M, −10.8% YoY) but no per-route table, so route
                    capture stays anchored to 2024.
                  </span>
                </div>
              )}
              <CaptureTable rows={apc.rows} />
              <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="text-[10px] text-text-muted">
                  Capture = measured lower-bound floor ÷ published weekday APC boardings. Floors use
                  the ground-truth calibrated pct→pax conversion; rebuild with{' '}
                  scripts/reconstruct_boardings.py + scripts/build_ridership_dataset.py. Sorted by
                  capture ascending.
                </span>
                <SourceNote source={apc.file ?? 'ridership.csv'} />
              </div>
            </>
          ) : (
            <div className="px-5 pb-5">
              <EmptyState
                title="No published-APC comparison yet"
                hint="Run scripts/build_ridership_dataset.py so ridership.csv carries the published boardings and measured lower-bound floors."
              />
            </div>
          )}
        </section>

        {/* ---- cross-links ---- */}
        <div className="rounded-2xl border border-border bg-card p-4">
          <p className="text-[10px] font-bold uppercase tracking-wider text-text-muted">What to do with this</p>
          <div className="mt-2 flex flex-col gap-2">
            {dw && dw.delta_min > 0.5 && (
              <a href="#optimize" className="group flex items-center gap-2 rounded-lg border border-border bg-bg/40 px-3 py-2.5 text-[11px] transition-colors hover:border-optimized/50 hover:bg-optimized/10">
                <span className="font-semibold text-text-primary group-hover:text-optimized">Fix transfers</span>
                <span className="text-text-muted">— re-run the optimizer knowing waits are ~{dw.delta_min.toFixed(1)} min worse than modeled</span>
                <ArrowRight className="ml-auto h-3 w-3 text-text-muted group-hover:text-optimized" />
              </a>
            )}
            <a href="#reliability" className="group flex items-center gap-2 rounded-lg border border-border bg-bg/40 px-3 py-2.5 text-[11px] transition-colors hover:border-optimized/50 hover:bg-optimized/10">
              <span className="font-semibold text-text-primary group-hover:text-optimized">Transfer reliability</span>
              <span className="text-text-muted">— see realized waits at every stop, mapped</span>
              <ArrowRight className="ml-auto h-3 w-3 text-text-muted group-hover:text-optimized" />
            </a>
          </div>
        </div>
      </div>
    </div>
  );
}